oxy_webhelp_navlinks = {"getting_started_with_rsc-d39307e1453":{"topics":[{"title":"<span class=\"ph\">RSC<\/span> hosting platforms","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">Rubrik Security Cloud<\/span> is hosted on Amazon Web Services (AWS) or Google Cloud         Platform (GCP).<span class=\"ph\"> Rubrik hosts accounts for European customers in the AWS             European Sovereign Cloud.<\/span><\/p>","href":"saas\/rsc_hosting_platforms.html","attributes":{"data-id":"rsc_hosting_platforms"},"menu":{"hasChildren":false},"tocID":"rsc_hosting_platforms-d39307e1469","topics":[]},{"title":"Adding the initial account","shortdesc":"<p class=\"shortdesc\">Use the instructions in the email sent by Rubrik to set up the initial         account.<\/p>","href":"saas\/adding_the_initial_account.html","attributes":{"data-id":"adding_the_initial_account"},"menu":{"hasChildren":false},"tocID":"adding_the_initial_account-d39307e1486","topics":[]},{"title":"<span class=\"ph\">RSC<\/span> password constraints","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> passwords must comply with the password constraints.<\/p>","href":"saas\/common\/password_constraints.html","attributes":{"data-id":"rbk_password_constraints"},"menu":{"hasChildren":false},"tocID":"rbk_password_constraints-d39307e1497","topics":[]},{"title":"Adding additional accounts","shortdesc":"<p class=\"shortdesc\">The initial <span class=\"ph\">RSC<\/span> user account, and every subsequently added user account, can add         additional users.<\/p>","href":"saas\/adding_additional_accounts.html","attributes":{"data-id":"adding_additional_accounts"},"menu":{"hasChildren":false},"tocID":"adding_additional_accounts-d39307e1512","topics":[]},{"title":"Changing the password","shortdesc":"<p class=\"shortdesc\">Change the password from the <span class=\"ph\">RSC<\/span> login page. <\/p>","href":"saas\/changing_the_password.html","attributes":{"data-id":"changing_the_password"},"menu":{"hasChildren":false},"tocID":"changing_the_password-d39307e1526","topics":[]},{"title":"Resetting the password","shortdesc":"<p class=\"shortdesc\">If you suspect your <span class=\"ph\">RSC<\/span> domain has been compromised or have other         security concerns, reset your password from the User Preferences page.<\/p>","href":"saas\/resetting_password.html","attributes":{"data-id":"resetting_password"},"menu":{"hasChildren":false},"tocID":"resetting_password-d39307e1540","topics":[]},{"title":"Local user account lockout","shortdesc":"<p class=\"shortdesc\">Local user accounts are automatically locked after a configured number of failed         login attempts or due to inactivity, enhancing security against unauthorized         access.<\/p>","href":"saas\/local_user_account_lockout.html","attributes":{"data-id":"local_user_account_lockout"},"menu":{"hasChildren":false},"tocID":"local_user_account_lockout-d39307e1554","topics":[]},{"title":"Switching <span class=\"ph\">RSC<\/span> user interface language to Japanese","shortdesc":"<p class=\"shortdesc\">To view the user interface of <span class=\"ph\">RSC<\/span> in Japanese language, open the User         Preferences page and switch the language to Japanese.<\/p>","href":"saas\/switching_ui_language_japanese.html","attributes":{"data-id":"switching_ui_language_japanese"},"menu":{"hasChildren":false},"tocID":"switching_ui_language_japanese-d39307e1565","topics":[]},{"title":"Web browser support","shortdesc":"<p class=\"shortdesc\">When using the <span class=\"ph\">RSC<\/span>web UI, the latest version of Google Chrome or         Microsoft Edge provides the best viewing experience.<\/p>","href":"saas\/web_browser_support_rsc.html","attributes":{"data-id":"web_browser_support_rsc"},"menu":{"hasChildren":false},"tocID":"web_browser_support_rsc-d39307e1582","topics":[]},{"title":"Settings menu","shortdesc":"<p class=\"shortdesc\">You can use the <span class=\"ph\">RSC<\/span> Settings menu to access and configure the         global settings for all your Rubrik applications.<\/p>","href":"saas\/rsc_settings_menu.html","attributes":{"data-id":"rsc_settings_menu"},"menu":{"hasChildren":false},"tocID":"rsc_settings_menu-d39307e1596","topics":[]},{"title":"Finding the <span class=\"ph\">RSC<\/span> domain region","shortdesc":"<p class=\"shortdesc\">Find the region in which your <span class=\"ph\">RSC<\/span> domain is running.<\/p>","href":"saas\/finding_rsc_region.html","attributes":{"data-id":"finding_rsc_region"},"menu":{"hasChildren":false},"tocID":"finding_rsc_region-d39307e1611","topics":[]},{"title":"Finding the <span class=\"ph\">RSC<\/span> outbound IP addresses","shortdesc":"<p class=\"shortdesc\">Locate the complete list of outbound IP addresses that <span class=\"ph\">RSC<\/span> uses to         connect to your SaaS application, and add them to your network allowlist.<\/p>","href":"saas\/finding_ip_address.html","attributes":{"data-id":"finding_ip_address"},"menu":{"hasChildren":false},"tocID":"finding_ip_address-d39307e1628","topics":[]},{"title":"Rubrik clusters","shortdesc":"<p class=\"shortdesc\">A Rubrik cluster is an instance of Rubrik CDM running on any virtual or physical         platform. You can add the Rubrik cluster to <span class=\"ph\">RSC<\/span> to enable extended features         for the cluster.<\/p>","href":"saas\/common\/rubrik_clusters.html","attributes":{"data-id":"rubrik_clusters"},"menu":{"hasChildren":false},"tocID":"rubrik_clusters-d39307e1645","next":"rubrik_clusters-d39307e1645"},{"title":"Customer Support for <span class=\"ph\">RSC<\/span>","shortdesc":"<p class=\"shortdesc\">You can grant support access and open and close a support tunnel in the Customer         Support menu. The support access feature enables Rubrik Support to access your <span class=\"ph\">RSC<\/span> domain securely in read-only mode. Rubrik Support uses the support         tunnel to examine the health of the Rubrik cluster and to troubleshoot and resolve issues.         You can also run network diagnostics from the Customer Support menu.<\/p>","href":"saas\/customer_support.html","attributes":{"data-id":"customer_support"},"menu":{"hasChildren":false},"tocID":"customer_support-d39307e1686","next":"customer_support-d39307e1686"},{"title":"<span class=\"ph\">RSC<\/span> Help Center","shortdesc":"<p class=\"shortdesc\">You can use the Help Center in <span class=\"ph\">RSC<\/span> to search product documentation,         access the Rubrik knowledge base, and create support cases.<\/p>","href":"saas\/rsc_hc.html","attributes":{"data-id":"rsc_self_help"},"menu":{"hasChildren":false},"tocID":"rsc_self_help-d39307e1820","next":"rsc_self_help-d39307e1820"},{"title":"Support Cases management in <span class=\"ph\">RSC<\/span>","shortdesc":"<p class=\"shortdesc\">The Support Cases page provides an integrated workspace in <span class=\"ph\">RSC<\/span> for         viewing, creating, and managing Rubrik support cases without leaving the         platform.<\/p>","href":"saas\/support_cases_management.html","attributes":{"data-id":"support_cases_management"},"menu":{"hasChildren":false},"tocID":"support_cases_management-d39307e1853","next":"support_cases_management-d39307e1853"},{"title":"<span class=\"ph\">RSC<\/span> domain URL change","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> enables you to change your <span class=\"ph\">RSC<\/span> domain URL without         losing any existing metadata or account configurations. This feature ensures continuous         workflow continuity, as only the domain URL itself changes, while your data and settings         remain unchanged.<\/p>","href":"saas\/rsc_domain_url_change.html","attributes":{"data-id":"rsc_domain_url_change"},"menu":{"hasChildren":false},"tocID":"rsc_domain_url_change-d39307e1905","topics":[]},{"title":"Date and time customization","shortdesc":"<p class=\"shortdesc\">Date and time is a setting under User Preferences that allows you to customize the         date and time settings based on your preferences.<\/p>","href":"saas\/date_and_time_customization.html","attributes":{"data-id":"date_and_time_customization"},"menu":{"hasChildren":false},"tocID":"date_and_time_customization-d39307e1923","next":"date_and_time_customization-d39307e1923"},{"title":"Notifications and release notes","shortdesc":"<p class=\"shortdesc\">You can access notifications and see information related to pending tasks on the         Notifications tab. You can view <span class=\"ph\">RSC<\/span> release information on the Release Notes         tab.<\/p>","href":"saas\/common\/notifications_release_notes.html","attributes":{"data-id":"notifications_release_notes"},"menu":{"hasChildren":false},"tocID":"notifications_release_notes-d39307e1956","next":"notifications_release_notes-d39307e1956"},{"title":"<span class=\"ph\">RSC<\/span> navigation history","shortdesc":"<p class=\"shortdesc\">You can view the navigation history for the recently visited pages in <span class=\"ph\">RSC<\/span>.<\/p>","href":"saas\/common\/navigation_history.html","attributes":{"data-id":"navigation_history"},"menu":{"hasChildren":false},"tocID":"navigation_history-d39307e2009","topics":[]},{"title":"<span class=\"ph\">RSC<\/span> web UI table data export","shortdesc":"<p class=\"shortdesc\">You can export the data available in tables in the <span class=\"ph\">RSC<\/span> web UI as CSV         files for further analysis or reporting.<\/p>","href":"saas\/common\/rsc_ui_table_data_export.html","attributes":{"data-id":"rsc_ui_table_data_export"},"menu":{"hasChildren":false},"tocID":"rsc_ui_table_data_export-d39307e2025","topics":[]}]}};